def row_echelon_full_matrix(m):
    operations = []
    for i in range(min(m.ncols(), m.nrows())):
        # Find the pivot in the current column (the first 1 in column i)
        pivot_row = None
        for r in range(i, m.nrows()):
            if m[r, i] == 1:
                pivot_row = r
                break

        # If no pivot is found, skip this column
        if pivot_row is None:
            swap_row_index = None
            for row_index in range(m.nrows() - 1)[::-1]:
                if m[row_index][row_index] == 0 and any(
                        m[row_index][k] == 1 for k in range(row_index + 1, m.nrows())):
                    swap_row_index = row_index
            if swap_row_index is not None and not m[swap_row_index + 1].is_zero():
                m[swap_row_index], m[swap_row_index + 1] = m[swap_row_index + 1], m[swap_row_index]
                operations.append((swap_row_index, swap_row_index + 1))
                operations.append((swap_row_index + 1, swap_row_index))
                operations.append((swap_row_index, swap_row_index + 1))
            else:
                continue
        else:
            # Swap the current row with the pivot row
            if pivot_row != i:
                m[[i, pivot_row]] = m[[pivot_row, i]]
                operations.append((i, pivot_row))
                operations.append((pivot_row, i))
                operations.append((i, pivot_row))

            # Eliminate all rows below the pivot
            for j in range(i + 1, m.nrows()):
                if m[j, i] == 1:
                    m[j] = (m[j] + m[i]) % 2
                    operations.append((j, i))

    return m, operations


def row_echelon_full_matrix(m):
    operations = []
    for i in range(min(m.ncols(), m.nrows())):
        # Find the pivot in the current column (the first 1 in column i)
        pivot_row = None
        for r in range(i, m.nrows()):
            if m[r, i] == 1:
                pivot_row = r
                break

        # If no pivot is found, skip this column
        if pivot_row is None:
            for row_index in range(1, m.nrows())[::-1]:
                if m[row_index].is_zero():
                    continue
                print(row_index)
                curr_pivot = get_pivot(m[row_index])
                prev_pivot = get_pivot(m[row_index - 1])
                print(curr_pivot, prev_pivot)
                print()
                if prev_pivot is None or (prev_pivot is not None and curr_pivot < prev_pivot):
                    m[row_index], m[row_index - 1] = m[row_index - 1], m[row_index]
                    operations.append((row_index, row_index + 1))
                    operations.append((row_index + 1, row_index))
                    operations.append((row_index, row_index + 1))
                else:
                    print("Do nothing")
            break

        # Swap the current row with the pivot row
        if pivot_row != i:
            m[[i, pivot_row]] = m[[pivot_row, i]]
            operations.append((i, pivot_row))
            operations.append((pivot_row, i))
            operations.append((i, pivot_row))

        # Eliminate all rows below the pivot
        for j in range(i + 1, m.nrows()):
            if m[j, i] == 1:
                m[j] = (m[j] + m[i]) % 2
                m[j] = (m[j] + m[i]) % 2
                operations.append((j, i))

    return m, operations


