def kernel(m):
    rows = len(m)
    cols = len(m[0])

    pivots = []
    free_columns = []
    row_index = 0
    k_base = []
    for j in range(cols):
        if row_index < rows and m[row_index][j] == 1:
            pivots.append(j)
            row_index += 1
        else:
            free_columns.append(j)
    for f_idx in free_columns:
        k_vector = [0 for _ in range(cols)]
        k_vector[f_idx] = 1
        for p_index in pivots[::-1]:
            s = 0
            for col in range(cols)[::-1]:
                if col != p_index:
                    s = (s + m[p_index][col] * k_vector[col]) % 2
            k_vector[p_index] = s
        k_base.append(k_vector)
    return k_base


def verify_ech(m):
    p_old = 0
    flags = []
    for r in range(m.nrows()):
        p = get_pivot(m[r])
        if p is not None:
            assert p_old <= p
            p_old = p
        else:
            if p_old is not None and p is None:
                flags.append(True)
            flags.append(False)
            p_old = p
    assert len([item for item in flags if item is True]) in [0, 1]


verify_ech(Matrix(GF(2), t1))


def kernel_echelon(m):
    rows = len(m)
    cols = len(m[0]) if rows > 0 else 0

    if rows == 0 or cols == 0:
        return []  # No kernel for an empty matrix

    pivots = []
    free_columns = []
    row_index = 0
    k_base = []

    # Identify pivots and free columns
    for j in range(cols):
        if row_index < rows and m[row_index][j] != 0:  # Non-zero entry marks a pivot
            pivots.append(j)
            row_index += 1
        else:
            free_columns.append(j)

    print("free cols", free_columns)
    # Construct kernel basis vectors for each free column
    for f_idx in free_columns:
        k_vector = [0] * cols
        k_vector[f_idx] = 1

        # Back-substitution to solve for pivot positions
        for pivot in pivots[::-1]:
            # Compute the contribution of the free variable to the pivot row
            s = 0
            for col in range(cols)[::-1]:
                s = (s + m[pivot][col] * k_vector[col]) % 2
            k_vector[pivot] = s

        k_base.append(k_vector)

    return k_base


