def echelon_form_with_operations(matrix):
    """
    Compute the echelon form of a matrix in GF(2),
    tracking the row operations performed.

    Args:
        matrix (Matrix): The input matrix in GF(2).

    Returns:
        tuple: (echelon_matrix, operations)
               - echelon_matrix: The echelon form of the input matrix.
               - operations: List of operations [(i, j), ...], where row(i) = row(i) + row(j).
    """
    # Ensure the matrix is in GF(2)
    matrix = matrix.change_ring(GF(2))

    # Initialize operations list
    operations = []

    # Get the dimensions of the matrix
    num_rows, num_cols = matrix.nrows(), matrix.ncols()

    pivot_row = 0  # Track the current pivot row
    for col in range(num_cols):
        # Find the first row with a leading 1 in the current column
        for row in range(pivot_row, num_rows):
            if matrix[row, col] == 1:
                # Swap rows to move the pivot to the top
                if row != pivot_row:
                    # matrix.swap_rows(pivot_row, row)
                    matrix[pivot_row], matrix[row] = matrix[pivot_row], matrix[row]
                    operations.append((pivot_row, row))  # Track the swap operation
                    operations.append((row, pivot_row))
                    operations.append((pivot_row, row))

                # Use the pivot row to eliminate other rows in this column
                for r in range(pivot_row + 1, num_rows):
                    if matrix[r, col] == 1:
                        matrix[r] = matrix[r] + matrix[pivot_row]
                        # matrix.add_row(r, pivot_row)  # row(r) = row(r) + row(pivot_row)
                        operations.append((r, pivot_row))  # Track the row addition operation

                pivot_row += 1  # Move to the next pivot row
                break

    return matrix, operations


