def print_matrix(matrix):
    for row in matrix:
        print(" ".join(map(str, row)))


def echelon_form_GF2_with_operations(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    lead = 0
    operations = []

    for r in range(rows):
        if lead >= cols:
            return matrix, operations
        i = r
        while matrix[i][lead] == 0:
            i += 1
            if i == rows:
                i = r
                lead += 1
                if lead == cols:
                    return matrix, operations
        matrix[r], matrix[i] = matrix[i], matrix[r]
        if matrix[r][lead] == 1:
            matrix[r] = [m % 2 for m in matrix[r]]
        for i in range(rows):
            if i != r and matrix[i][lead] == 1:
                matrix[i] = [(x + y) % 2 for x, y in zip(matrix[i], matrix[r])]
                operations.append((i, r))
        lead += 1
    return matrix, operations


