def generalized_echelon_form_GF2(matrix):
    def get_pivot(row):
        for idx, val in enumerate(row):
            if val != 0:
                return idx
        return None

    def copy(matrix):
        return [row[:] for row in matrix]

    m_copy = copy(matrix)
    rows = len(m_copy)
    cols = len(m_copy[0])
    operations = []

    for r in range(rows):
        # Find the pivot in the current row
        p_index = get_pivot(m_copy[r])
        if p_index is None:
            continue

        # Move the row with the pivot to the current position if necessary
        if p_index != r:
            m_copy[r], m_copy[p_index] = m_copy[p_index], m_copy[r]
            operations.append((r, p_index))
            operations.append((p_index, r))
            operations.append((r, p_index))

        # Perform row operations to create zeros below the pivot
        for i in range(r + 1, rows):
            if m_copy[i][p_index] == 1:
                m_copy[i] = [(x + y) % 2 for x, y in zip(m_copy[i], m_copy[r])]
                operations.append((i, r))

    return m_copy, operations


